require_once __DIR__.'/includes/auth.php';require_login();$err='';$st=$pdo->prepare("SELECT user_id,full_name,username FROM users WHERE user_id<>? AND status='active' ORDER BY full_name");$st->execute([current_user_id()]);$users=$st->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim((string)($_POST['title']??''));$members=array_values(array_unique(array_map('intval',$_POST['members']??[])));$members=array_values(array_filter($members,fn($v)=>$v>0&&$v!==current_user_id()));if(mb_strlen($title)<2||mb_strlen($title)>120)$err='Group name must be 2–120 characters.';elseif(count($members)<1)$err='Select at least one other member.';else{$place=implode(',',array_fill(0,count($members),'?'));$st=$pdo->prepare("SELECT user_id FROM users WHERE status='active' AND user_id IN ($place)");$st->execute($members);$valid=array_map('intval',array_column($st->fetchAll(),'user_id'));if(count($valid)!==count($members))$err='One or more selected users are unavailable.';else{$pdo->beginTransaction();try{$st=$pdo->prepare("INSERT INTO conversations(conversation_type,title,created_by) VALUES('group',?,?)");$st->execute([$title,current_user_id()]);$cid=(int)$pdo->lastInsertId();$st=$pdo->prepare("INSERT INTO conversation_members(conversation_id,user_id,member_role) VALUES(?,?,'admin')");$st->execute([$cid,current_user_id()]);$st=$pdo->prepare("INSERT INTO conversation_members(conversation_id,user_id,member_role) VALUES(?,?,'member')");foreach($valid as $id)$st->execute([$cid,$id]);$pdo->commit();header('Location: chat.php?id='.$cid);exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err='Could not create group. Please try again.';}}}}$pageTitle='Create group';require __DIR__.'/includes/header.php';?>
<section class="standalone-panel"><a class="back-link" href="dashboard.php">← Back to messages</a><div class="eyebrow">BRING PEOPLE TOGETHER</div><h1>Create a group</h1><p class="muted">Choose a name and at least one other member.</p><?php if($err): ?><div class="alert alert-error"><?= e($err) ?></div><?php endif; ?><form method="post" class="form-stack"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Group name<input name="title" maxlength="120" required placeholder="e.g. TY Project Team"></label><fieldset class="member-picker"><legend>Select members</legend><?php if(!$users): ?><p class="muted">Create another account first to test group chat.</p><?php endif; ?><?php foreach($users as $u): ?><label class="check-row"><input type="checkbox" name="members[]" value="<?= (int)$u['user_id'] ?>"><span><strong><?= e($u['full_name']) ?></strong><small>@<?= e($u['username']) ?></small></span></label><?php endforeach; ?></fieldset><button class="button button-primary" type="submit">Create group →</button></form></section><?php require __DIR__.'/includes/footer.php';?>
